import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3d_3d(
    .param .u64 in_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 D_in,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 C_out,
    .param .u32 KD,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_d,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .s32 pad_d,
    .param .s32 pad_h,
    .param .s32 pad_w,
    .param .u32 dil_d,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 in_s0,
    .param .u32 in_s1,
    .param .u32 in_s2,
    .param .u32 in_s3,
    .param .u32 in_s4,
    .param .u32 out_s0,
    .param .u32 out_s1,
    .param .u32 out_s2,
    .param .u32 out_s3,
    .param .u32 out_s4,
    .param .u32 D_out,
    .param .u32 H_out,
    .param .u32 W_out
)
{
    .reg .pred  %p<7>;
    .reg .b32   %r<80>;
    .reg .b64   %rd<60>;
    .reg .f32   %f<6>;

    // Load params
    ld.param.u64  %rd1,  [in_ptr];
    ld.param.u64  %rd2,  [weight_ptr];
    ld.param.u64  %rd3,  [bias_ptr];
    ld.param.u64  %rd4,  [out_ptr];

    ld.param.u32  %rN,   [N];
    ld.param.u32  %rCi,  [C_in];
    ld.param.u32  %rDi,  [D_in];
    ld.param.u32  %rHi,  [H_in];
    ld.param.u32  %rWi,  [W_in];
    ld.param.u32  %rCo,  [C_out];

    ld.param.u32  %rKD,  [KD];
    ld.param.u32  %rKH,  [KH];
    ld.param.u32  %rKW,  [KW];

