    ld.param.s32  %rPh,  [pad_h];
    ld.param.s32  %rPw,  [pad_w];

    ld.param.u32  %rDd,  [dil_d];
    ld.param.u32  %rDh,  [dil_h];
    ld.param.u32  %rDw,  [dil_w];

    ld.param.u32  %rG,   [groups];

