class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0, "in_channels must be divisible by groups"
        assert out_channels % groups == 0, "out_channels must be divisible by groups"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        KD = kernel_size
        KH = kernel_size
        KW = 1

        weight = torch.empty(out_channels, in_channels // groups, KD, KH, KW)
        self.weight = nn.Parameter(weight)
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None

        # Initialize as nn.Conv3d
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (in_channels // groups) * KD * KH * KW
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        assert x.dim() == 5, "Expected 5D tensor (N, C, D, H, W)"

        N, Cin, Di, Hi, Wi = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"

        KD = self.kernel_size
        KH = self.kernel_size
        KW = 1

        Sd = Sh = Sw = int(self.stride)
        Pd = Ph = Pw = int(self.padding)
        Dd = Dh = Dw = int(self.dilation)

        Do = (Di + 2 * Pd - Dd * (KD - 1) - 1) // Sd + 1
        Ho = (Hi + 2 * Ph - Dh * (KH - 1) - 1) // Sh + 1
        Wo = (Wi + 2 * Pw - Dw * (KW - 1) - 1) // Sw + 1

        out = torch.empty((N, self.out_channels, Do, Ho, Wo), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        in_strides = x.stride()
        out_strides = out.stride()

        total = N * self.out_channels * Do * Ho * Wo
        block = 256
        grid_x = (total + block - 1) // block
        if grid_x == 0:
            return out

        args = [
            x,                              # in_ptr
            self.weight,                    # weight_ptr
            (self.bias if self.bias is not None else u64(0)),  # bias_ptr
            out,                            # out_ptr
            i32(N),
            i32(Cin),
            i32(Di),
            i32(Hi),
            i32(Wi),
