    @%p0 bra      DONE;
    // Decode indices from linear id (u64 divisions/mods)
    mov.u64       %rdTmp, %rdLin;
    // w = rdTmp % W_out
    rem.u64       %rdRem, %rdTmp, %rdWo;
    div.u64       %rdTmp, %rdTmp, %rdWo;
    cvt.u32.u64   %rOw, %rdRem;
    // h = rdTmp % H_out
    cvt.u64.u32   %rdHo2, %rHo;
    rem.u64       %rdRem, %rdTmp, %rdHo2;
    div.u64       %rdTmp, %rdTmp, %rdHo2;
    cvt.u32.u64   %rOh, %rdRem;
    // d = rdTmp % D_out
    cvt.u64.u32   %rdDo2, %rDo;
    rem.u64       %rdRem, %rdTmp, %rdDo2;
    div.u64       %rdTmp, %rdTmp, %rdDo2;
    cvt.u32.u64   %rOd, %rdRem;
    // oc = rdTmp % C_out
    cvt.u64.u32   %rdCo2, %rCo;
    rem.u64       %rdRem, %rdTmp, %rdCo2;
    div.u64       %rdTmp, %rdTmp, %rdCo2;
    cvt.u32.u64   %rOc, %rdRem;
    // n = rdTmp
    cvt.u32.u64   %rOn, %rdTmp;
    // Compute group sizes and group index
    div.u32       %rCinG, %rCi, %rG;   // C_in per group
    div.u32       %rCoutG, %rCo, %rG;  // C_out per group
    div.u32       %rGidx, %rOc, %rCoutG;
    // ic base = gidx * CinG
    mul.lo.u32    %rIcBase, %rGidx, %rCinG;
    // Prepare some s32 versions
    cvt.s32.u32   %rOd_s, %rOd;
    cvt.s32.u32   %rOh_s, %rOh;
    cvt.s32.u32   %rOw_s, %rOw;
    cvt.s32.u32   %rSd_s, %rSd;
    cvt.s32.u32   %rSh_s, %rSh;
    cvt.s32.u32   %rSw_s, %rSw;
    cvt.s32.u32   %rDd_s, %rDd;
    cvt.s32.u32   %rDh_s, %rDh;
    cvt.s32.u32   %rDw_s, %rDw;
    cvt.s32.u32   %rDi_s, %rDi;
    cvt.s32.u32   %rHi_s, %rHi;
    cvt.s32.u32   %rWi_s, %rWi;
    // Accumulator
    mov.f32       %fAcc, 0f00000000;
    // kd loop
    mov.u32       %rKD_it, 0;
KD_LOOP:
    setp.ge.u32   %p1, %rKD_it, %rKD;
    @%p1 bra      KD_END;
    // id = od*stride_d - pad_d + kd*dil_d
    mul.lo.s32    %rTmp1, %rOd_s, %rSd_s;
    sub.s32       %rTmp1, %rTmp1, %rPd;
    cvt.s32.u32   %rKD_it_s, %rKD_it;
    mul.lo.s32    %rTmp2, %rKD_it_s, %rDd_s;
    add.s32       %rId_s, %rTmp1, %rTmp2;
    // bounds check id
    setp.lt.s32   %p2, %rId_s, 0;
    @%p2 bra      KD_CONT;
    setp.ge.s32   %p3, %rId_s, %rDi_s;
    @%p3 bra      KD_CONT;
    // kh loop
    mov.u32       %rKH_it, 0;
KH_LOOP:
    setp.ge.u32   %p4, %rKH_it, %rKH;
    @%p4 bra      KH_END;
    // ih = oh*stride_h - pad_h + kh*dil_h
    mul.lo.s32    %rTmp3, %rOh_s, %rSh_s;
    sub.s32       %rTmp3, %rTmp3, %rPh;
    cvt.s32.u32   %rKH_it_s, %rKH_it;
    mul.lo.s32    %rTmp4, %rKH_it_s, %rDh_s;
    add.s32       %rIh_s, %rTmp3, %rTmp4;
    // bounds check ih
    setp.lt.s32   %p5, %rIh_s, 0;
    @%p5 bra      KH_CONT;
    setp.ge.s32   %p6, %rIh_s, %rHi_s;
    @%p6 bra      KH_CONT;
    // kw loop
    mov.u32       %rKW_it, 0;
KW_LOOP:
    setp.ge.u32   %p0, %rKW_it, %rKW;
    @%p0 bra      KW_END;
    // iw = ow*stride_w - pad_w + kw*dil_w
    mul.lo.s32    %rTmp5, %rOw_s, %rSw_s;
    sub.s32       %rTmp5, %rTmp5, %rPw;
    cvt.s32.u32   %rKW_it_s, %rKW_it;
    mul.lo.s32    %rTmp6, %rKW_it_s, %rDw_s;
    add.s32       %rIw_s, %rTmp5, %rTmp6;
    // bounds check iw
    setp.lt.s32   %p1, %rIw_s, 0;
    @%p1 bra      KW_CONT;
    setp.ge.s32   %p2, %rIw_s, %rWi_s;
    @%p2 bra      KW_CONT;
    // Loop over input channels in group
    mov.u32       %rIc_g, 0;
IC_LOOP:
    setp.ge.u32   %p3, %rIc_g, %rCinG;
    @%p3 bra      IC_END;
    // ic = ic_base + ic_g
    add.u32       %rIc, %rIcBase, %rIc_g;
    // Compute input offset in elements (use 64-bit accumulation)
    // off = n*IS0 + ic*IS1 + id*IS2 + ih*IS3 + iw*IS4
    // Convert indices to u32
    cvt.u32.s32   %rId_u, %rId_s;
    cvt.u32.s32   %rIh_u, %rIh_s;
    cvt.u32.s32   %rIw_u, %rIw_s;
    mul.wide.u32  %rdOff0, %rOn,  %rIS0;
    mul.wide.u32  %rdOff1, %rIc,  %rIS1;
    mul.wide.u32  %rdOff2, %rId_u, %rIS2;
    mul.wide.u32  %rdOff3, %rIh_u, %rIS3;
    mul.wide.u32  %rdOff4, %rIw_u, %rIS4;
    add.s64       %rdOff01, %rdOff0, %rdOff1;
    add.s64       %rdOff23, %rdOff2, %rdOff3;
    add.s64       %rdOff,   %rdOff01, %rdOff23;
    add.s64       %rdOff,   %rdOff, %rdOff4;
    // to bytes
    shl.b64       %rdInByte, %rdOff, 2; // *4
    add.s64       %rdInAddr, %rd1, %rdInByte;
    // Load input value
    ld.global.f32 %fIn, [%rdInAddr];
    // Compute weight offset:
    // idx = ((((oc * CinG) + ic_g) * KD + kd) * KH + kh) * KW + kw
    // accumulate in 64-bit, then bytes
    mul.wide.u32  %rdW0, %rOc, %rCinG;      // oc * CinG
    cvt.u64.u32   %rdIc_g_u64, %rIc_g;
    add.u64       %rdW0, %rdW0, %rdIc_g_u64;     // + ic_g
    cvt.u64.u32   %rdKD_u, %rKD;
    cvt.u64.u32   %rdKH_u, %rKH;
    cvt.u64.u32   %rdKW_u, %rKW;
    mul.lo.u64    %rdW1, %rdW0, %rdKD_u;    // * KD
    cvt.u64.u32   %rd_kd, %rKD_it;
    add.u64       %rdW1, %rdW1, %rd_kd;     // + kd
    mul.lo.u64    %rdW2, %rdW1, %rdKH_u;    // * KH
    cvt.u64.u32   %rd_kh, %rKH_it;
    add.u64       %rdW2, %rdW2, %rd_kh;     // + kh
    mul.lo.u64    %rdW3, %rdW2, %rdKW_u;    // * KW
    cvt.u64.u32   %rd_kw, %rKW_it;
    add.u64       %rdW3, %rdW3, %rd_kw;     // + kw
    shl.b64       %rdWByte, %rdW3, 2;       // *4
    add.s64       %rdWAddr, %rd2, %rdWByte;
    // Load weight value
    ld.global.f32 %fW, [%rdWAddr];
    // FMA
    fma.rn.f32    %fAcc, %fIn, %fW, %fAcc;
    // next ic_g
    add.u32       %rIc_g, %rIc_g, 1;
    bra           IC_LOOP;
IC_END:
KW_CONT:
    // next kw
    add.u32       %rKW_it, %rKW_it, 1;
    bra           KW_LOOP;
KW_END:
KH_CONT:
    // next kh
    add.u32       %rKH_it, %rKH_it, 1;
    bra           KH_LOOP;
KH_END:
KD_CONT:
    // next kd
    add.u32       %rKD_it, %rKD_it, 1;
    bra           KD_LOOP;
KD_END:
    // Add bias if provided
    mov.u64       %rdZero, 0;
    setp.eq.u64   %p0, %rd3, %rdZero;
    @%p0 bra      NOBIAS;
    // bias_addr = bias_ptr + oc*4
    mul.wide.u32  %rdBOff, %rOc, 4;
    add.s64       %rdBAddr, %rd3, %rdBOff;
    ld.global.f32 %fB, [%rdBAddr];
    add.f32       %fAcc, %fAcc, %fB;
NOBIAS:
    // Store to output
    // out_off = n*OS0 + oc*OS1 + od*OS2 + oh*OS3 + ow*OS4
    mul.wide.u32  %rdO0, %rOn, %rOS0;
    mul.wide.u32  %rdO1, %rOc, %rOS1;
    mul.wide.u32  %rdO2, %rOd, %rOS2;
    mul.wide.u32  %rdO3, %rOh, %rOS3;
    mul.wide.u32  %rdO4, %rOw, %rOS4;
    add.s64       %rdOA, %rdO0, %rdO1;
    add.s64       %rdOB, %rdO2, %rdO3;
    add.s64       %rdOC, %rdOA, %rdOB;
    add.s64       %rdOO, %rdOC, %rdO4;
    shl.b64       %rdOutByte, %rdOO, 2;
    add.s64       %rdOutAddr, %rd4, %rdOutByte;
    st.global.f32 [%rdOutAddr], %fAcc;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3d_3d")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        assert in_channels % groups == 0, "in_channels must be divisible by groups"
        assert out_channels % groups == 0, "out_channels must be divisible by groups"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        KD = kernel_size
        KH = kernel_size
        KW = 1

        weight = torch.empty(out_channels, in_channels // groups, KD, KH, KW)
        self.weight = nn.Parameter(weight)
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None

        # Initialize as nn.Conv3d
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (in_channels // groups) * KD * KH * KW
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        assert x.dim() == 5, "Expected 5D tensor (N, C, D, H, W)"

        N, Cin, Di, Hi, Wi = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"

        KD = self.kernel_size
        KH = self.kernel_size
        KW = 1

        Sd = Sh = Sw = int(self.stride)
        Pd = Ph = Pw = int(self.padding)
        Dd = Dh = Dw = int(self.dilation)

        Do = (Di + 2 * Pd - Dd * (KD - 1) - 1) // Sd + 1
        Ho = (Hi + 2 * Ph - Dh * (KH - 1) - 1) // Sh + 1
        Wo = (Wi + 2 * Pw - Dw * (KW - 1) - 1) // Sw + 1

        out = torch.empty((N, self.out_channels, Do, Ho, Wo), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        in_strides = x.stride()
        out_strides = out.stride()

        total = N * self.out_channels * Do * Ho * Wo
        block = 256
        grid_x = (total + block - 1) // block
        if grid_x == 0:
            return out

        args = [
            x,                              # in_ptr
            self.weight,                    # weight_ptr
            (self.bias if self.bias is not None else u64(0)),  # bias_ptr
            out,                            # out_ptr
            i32(N),
            i32(Cin),
            i32(Di),
            i32(Hi),
            i32(Wi),
            i32(self.out_channels),
            i32(KD),
            i32(KH),
            i32(KW),
            i32(Sd),
            i32(Sh),
            i32(Sw),
            i32(Pd),
            i32(Ph),
            i32(Pw),
            i32(Dd),
            i32(Dh),
            i32(Dw),
            i32(self.groups),
            i32(in_strides[0]),
            i32(in_strides[1]),
            i32(in_strides[2]),
            i32(in_strides[3]),
            i32(in_strides[4]),
            i32(out_strides[0]),
            i32(out_strides[1]),
            i32(out_strides[2]),
            i32(out_strides[3]),
            i32(out_strides[4]),
            i32(Do),
            i32(Ho),
            i32(Wo),
        ]

        module.launch(
            "conv3d_3d",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=args,
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
